{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--ink:#0f1720;--muted:#64748b;--accent:#6b8e7a;--card:#fff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--ink);background:linear-gradient(180deg,#fbfcfd 0%, #f7f9fa 100%);-webkit-font-smoothing:antialiased;line-height:1.5}
    header{position:sticky;top:0;backdrop-filter: blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.4));border-bottom:1px solid rgba(15,23,32,0.04);z-index:40}
    .navwrap{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:14px}
    .brand{font-weight:600;letter-spacing:0.2px}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-size:15px}
    nav a.primary{color:var(--accent);font-weight:600}
    main{max-width:1100px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:22px;align-items:center}
    .card{background:var(--card);padding:26px;border-radius:12px;box-shadow:0 8px 30px rgba(16,24,40,0.06);}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .two{display:grid;grid-template-columns:1fr 360px;gap:24px;margin-top:18px}
    .bio{white-space:pre-wrap}
    .panel{position:relative}
    .pattern{position:absolute;inset:0;opacity:0.06;pointer-events:none}

    /* reveal utility */
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms ease,transform 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}

    /* modal */
    .try-btn{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#5f7d63);color:white;text-decoration:none;font-weight:600}
    .modal-backdrop{position:fixed;inset:0;background:rgba(3,7,18,0.45);display:none;align-items:center;justify-content:center;padding:20px;z-index:80}
    .modal{max-width:720px;width:100%;background:linear-gradient(180deg,rgba(255,255,255,0.98),rgba(250,250,250,0.95));border-radius:12px;padding:20px;box-shadow:0 30px 60px rgba(2,6,23,0.35)}
    .modal header{display:flex;align-items:center;justify-content:space-between}
    .tabs{display:flex;gap:8px;margin-top:12px}
    .tab{padding:8px 10px;border-radius:8px;background:rgba(11,20,15,0.03);cursor:pointer}
    .tab.active{background:var(--accent);color:white}
    .modal .content{margin-top:14px}
    .breath-circle{width:160px;height:160px;border-radius:50%;background:radial-gradient(circle at 30% 30%, #e8f4eb, #f6fbf9);margin:18px auto;display:grid;place-items:center;font-weight:700;color:#365a46}

    footer{max-width:1100px;margin:48px auto;color:var(--muted);padding:0 20px}

    /* small screens */
    @media(min-width:900px){.hero{grid-template-columns:1fr 360px}}    
  </style>
</head>
<body>
  <header>
    <div class="navwrap">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="about.html" class="primary">Meet</a>
        <a href="specialties.html">Offerings</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Investment</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero card reveal" aria-labelledby="about-heading">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
        <div>
          <h1 id="about-heading">A steady, plainspoken practice for days that feel dense</h1>
          <p class="lead">I offer thoughtful, evidence-informed psychotherapy for adults who want steadier footing. I aim to make sessions practical, honest, and quietly purposeful.</p>
        </div>
        <div style="text-align:right">
          <a class="try-btn" id="open-try">Try a short exercise</a>
          <div style="height:8px"></div>
          <a href="{{PRIMARY_CTA_URL}}" class="try-btn" style="background:linear-gradient(90deg,#2b6e53,#305b4b)">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>

      <div class="two" style="margin-top:18px">
        <div class="card panel reveal">
          <svg class="pattern" width="160" height="160" viewBox="0 0 160 160" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#dfeee2"/>
                <stop offset="1" stop-color="#f6fbf9"/>
              </linearGradient>
            </defs>
            <rect width="160" height="160" rx="12" fill="url(#g1)"/>
            <g fill="none" stroke="#e6f2ea" stroke-width="1">
              <path d="M10 120c20-40 80-40 120-20"/>
              <path d="M0 60c30 10 70 10 120-10"/>
              <circle cx="24" cy="36" r="2" fill="#cfe7d8" stroke="none"/>
            </g>
          </svg>

          <div class="bio">
            <p style="margin:0 0 8px; font-weight:600">I’m a licensed clinician practicing in {{CITY}}, {{STATE}}. My work blends relational reflection with practical skill-building so that ideas from session land inside daily life.</p>
            <p style="margin:0;color:var(--muted)">I have experience supporting people coping with anxiety, life transitions, grief, and relational strain. My approach privileges clarity, collaboration, and slow momentum.</p>
          </div>
        </div>

        <aside class="card panel reveal" aria-labelledby="contact-title">
          <h3 id="contact-title" style="margin:0 0 8px">Practice details</h3>
          <p style="margin:0;color:var(--muted)">Sessions are confidential within legal limits. Not a crisis service—if you are in immediate danger, call emergency services or crisis lines.</p>
          <hr style="margin:12px 0;border:none;border-top:1px solid rgba(15,23,32,0.06)">
          <p style="margin:8px 0"><strong>Phone</strong><br><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p style="margin:8px 0"><strong>Email</strong><br><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <div style="margin-top:12px">
            <a href="book.html" class="try-btn">Schedule a first session</a>
          </div>
        </aside>
      </div>
    </section>

    <section class="card" style="margin-top:20px;padding:22px" id="statement">
      <h2 style="margin:0 0 8px">A short note on boundaries and scope</h2>
      <p style="margin:0;color:var(--muted)">I cannot offer legal or medical advice. Therapy focuses on emotional, relational, and behavioral concerns. If you need pharmacological management, I will coordinate with your prescriber or refer you to appropriate services.</p>
    </section>

    <section class="card reveal" style="margin-top:20px;padding:22px" id="values">
      <h2 style="margin:0 0 8px">Ways I work</h2>
      <ul style="margin:0;color:var(--muted);padding-left:18px">
        <li>Pragmatic reflection that connects feeling and choice</li>
        <li>Short skill-building exercises for everyday situations</li>
        <li>Session plans shaped by what matters to you right now</li>
      </ul>
    </section>

  </main>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
      <div style="max-width:60%">© <span id="brand">{{BUSINESS_NAME}}</span> — Licensed clinician in {{STATE}} • Confidentiality within legal limits</div>
      <nav style="display:flex;gap:12px;margin-top:8px"><a href="privacy.html" style="color:var(--muted);text-decoration:none">Privacy</a></nav>
    </div>
  </footer>

  <!-- Try-it-now modal -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <header>
        <strong id="modal-title">Short practice</strong>
        <button id="close-modal" aria-label="Close" style="background:none;border:0;font-weight:600;cursor:pointer">Close</button>
      </header>

      <div class="tabs" role="tablist" aria-label="Practice tabs">
        <div class="tab active" data-tab="breath" role="tab" tabindex="0">Breathing</div>
        <div class="tab" data-tab="journal" role="tab" tabindex="0">Journal</div>
        <div class="tab" data-tab="intention" role="tab" tabindex="0">Set an intention</div>
      </div>

      <div class="content" id="modal-content">
        <div data-panel="breath">
          <div style="text-align:center">
            <div class="breath-circle" id="breath-circle">Breathe</div>
            <div style="display:flex;gap:8px;justify-content:center;margin-top:8px"><button id="start-breath" class="tab">Start</button><button id="stop-breath" class="tab">Stop</button></div>
            <p style="color:var(--muted);margin-top:12px">A paced breathing practice. Follow the circle and the counts for a minute.</p>
          </div>
        </div>

        <div data-panel="journal" style="display:none">
          <label style="font-weight:600">A brief prompt</label>
          <p style="margin:8px 0;color:var(--muted)">Name one small thing you can do this week to tend to yourself. Write freely for a few minutes.</p>
          <textarea id="journal-text" style="width:100%;height:120px;border-radius:8px;padding:10px;border:1px solid rgba(15,23,32,0.06)"></textarea>
          <div style="margin-top:8px;display:flex;gap:8px"><button id="save-journal" class="tab">Save</button><button id="clear-journal" class="tab">Clear</button></div>
          <p id="journal-saved" style="color:var(--accent);display:none;margin-top:8px">Saved to this device.</p>
        </div>

        <div data-panel="intention" style="display:none">
          <label style="font-weight:600">Set a steady intention</label>
          <p style="margin:8px 0;color:var(--muted)">A phrase you can return to when things feel diffuse.</p>
          <input id="intention-input" placeholder="I will..." style="width:100%;padding:10px;border-radius:8px;border:1px solid rgba(15,23,32,0.06)" />
          <div style="margin-top:8px;display:flex;gap:8px"><button id="save-intent" class="tab">Keep</button><button id="clear-intent" class="tab">Clear</button></div>
          <p id="intent-saved" style="color:var(--accent);display:none;margin-top:8px">Kept for this device.</p>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){
        reveals.forEach(function(el){el.classList.add('visible');});
        return;
      }
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(entry){
          if(entry.isIntersecting){entry.target.classList.add('visible');io.unobserve(entry.target);} 
        });
      },{threshold:0.12});
      reveals.forEach(function(el){io.observe(el);});
    })();

    // Modal and tabs
    (function(){
      var modal = document.getElementById('modal');
      var open = document.getElementById('open-try');
      var close = document.getElementById('close-modal');
      var tabs = Array.from(document.querySelectorAll('.tab[data-tab]'));
      var panels = Array.from(document.querySelectorAll('[data-panel]'));

      function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
      function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.body.style.overflow='auto'; }
      open.addEventListener('click', openModal); close.addEventListener('click', closeModal);
      modal.addEventListener('click', function(e){ if(e.target===modal) closeModal(); });

      tabs.forEach(function(t){ t.addEventListener('click', function(){
        tabs.forEach(function(x){x.classList.remove('active')}); t.classList.add('active');
        var sel = t.getAttribute('data-tab');
        panels.forEach(function(p){ p.style.display = (p.getAttribute('data-panel')===sel)?'block':'none'; });
      });
      t.addEventListener('keydown', function(e){ if(e.key==='Enter' || e.key===' ') t.click(); });
      });

      // Breathing exercise
      var circle = document.getElementById('breath-circle');
      var start = document.getElementById('start-breath');
      var stop = document.getElementById('stop-breath');
      var breathTimer = null; var phase = 0; // 0 inhale,1 hold,2 exhale
      var durations = [4000,1200,6000];
      function stepBreath(){
        clearTimeout(breathTimer);
        if(phase===0){ circle.style.transform='scale(1.18)'; circle.textContent='Inhale'; }
        else if(phase===1){ circle.style.transform='scale(1.05)'; circle.textContent='Hold'; }
        else { circle.style.transform='scale(0.92)'; circle.textContent='Exhale'; }
        breathTimer = setTimeout(function(){ phase=(phase+1)%3; stepBreath(); }, durations[phase]);
      }
      start.addEventListener('click', function(){ if(breathTimer) clearTimeout(breathTimer); phase=0; stepBreath(); });
      stop.addEventListener('click', function(){ clearTimeout(breathTimer); breathTimer=null; circle.style.transform='none'; circle.textContent='Breathe'; });

      // Journal storage
      var jtxt = document.getElementById('journal-text'); var saveJ = document.getElementById('save-journal'); var clearJ = document.getElementById('clear-journal'); var savedNote = document.getElementById('journal-saved');
      try{ var stored = localStorage.getItem('pp_journal'); if(stored){ jtxt.value = stored; savedNote.style.display='block'; savedNote.textContent='A previous note is loaded.'; }}catch(e){}
      saveJ.addEventListener('click', function(){ try{ localStorage.setItem('pp_journal', jtxt.value); savedNote.style.display='block'; savedNote.textContent='Saved to this device.'; }catch(e){} });
      clearJ.addEventListener('click', function(){ jtxt.value=''; try{ localStorage.removeItem('pp_journal'); }catch(e){} savedNote.style.display='none'; });

      // Intention storage
      var intentInput = document.getElementById('intention-input'); var saveIntent = document.getElementById('save-intent'); var clearIntent = document.getElementById('clear-intent'); var intentSaved = document.getElementById('intent-saved');
      try{ var st = localStorage.getItem('pp_intent'); if(st){ intentInput.value = st; intentSaved.style.display='block'; intentSaved.textContent='An intention is kept.'; }}catch(e){}
      saveIntent.addEventListener('click', function(){ try{ localStorage.setItem('pp_intent', intentInput.value); intentSaved.style.display='block'; intentSaved.textContent='Kept for this device.'; }catch(e){} });
      clearIntent.addEventListener('click', function(){ intentInput.value=''; try{ localStorage.removeItem('pp_intent'); }catch(e){} intentSaved.style.display='none'; });
    })();
  </script>
</body>
</html>"} 
