<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfbf8;--ink:#0f1720;--muted:#5b6974;--accent:#7a6fb0;--card:#fff}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial;background:var(--bg);color:var(--ink)}
    header{position:sticky;top:0;background:rgba(255,255,255,0.85);backdrop-filter:blur(6px);border-bottom:1px solid rgba(15,23,32,0.04)}
    .navwrap{max-width:1100px;margin:0 auto;padding:12px;display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none}
    main{max-width:1100px;margin:28px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .panel{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 12px 30px rgba(14,20,25,0.05)}
    h1{margin:0 0 8px}
    .service{border-radius:10px;padding:14px;border:1px solid rgba(15,23,32,0.04);margin-bottom:12px}
    .muted{color:var(--muted)}

    .pricing{display:flex;flex-direction:column;gap:10px}
    .price-card{padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfbff);border:1px solid rgba(15,23,32,0.04)}
